#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
r"""sources: 语义漂移修复器 —— 把「L1 页挂在 sources: 里」的条目移出语义字段。

背景（2026-10-25 体检 §四 #3）
------------------------------
`qc_evidence_base.classify()` 只统计**能解析到 source 卡**的条目；实测 52 个
concept/topic 页的 `sources:` 里有 **107 条**解析不到 source 页。逐条查明：
它们**不是路径拼错**，而是**语义漂移**——把 `[[concepts/…]]` / `[[topics/…]]`
（本库的二手综合，L1）当成一手文献挂进了 `sources:`（L2 专用字段）。
另有 1 条 `[[entities/…]]`、1 条项目 evidence 页、1 条 GitHub 外部 URL。

⇒ 正确改法不是改文件名（改名只会让「concept 冒充 source」变成「concept 冒充得更像」），
   而是**把它移出 `sources:`**：正文已有链接的直接删行；正文没有的移到 `## 参见`。

判定（纯函数，可被 --selftest 反算）
------------------------------------
    keep     条目解析到真实 source 卡（`wiki/sources/` 或 `projects/*/sources/`）
    move     条目是 wikilink，目标页存在但不是 source 卡 → 删行 + 正文补链
    external 条目是 http(s) 外链 → 删行 + 正文「来源/参考」注明无库内 source 卡
    orphan   目标页在库内找不到 → **不删**，报 BLOCKER（先把真坏链暴露出来）

纪律
----
· 默认**干跑**，`--apply` 才落盘；落盘前备份 `.qc_backup_YYYYMMDD/`，写后复算。
· 只改三处：`sources:` 的条目行、正文 `## 参见` 的追加行、`updated:`。
  不整篇重写（逐行操作，其余字节不变）。
· 换行走 `kb_lib.write_text_verified`（按多数票保留，混合文件点名）。
· 幂等：修完再跑一遍必须是 0 改动。

用法
----
    python tools/qc_sources_drift.py            # 干跑，打印逐页清单
    python tools/qc_sources_drift.py --apply    # 落盘
    python tools/qc_sources_drift.py --selftest # 夹具反算判定与改写函数
    python tools/qc_sources_drift.py --json out.json
"""
import os
import re
import sys
import json
import glob
import shutil
import datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import (read_text, split_frontmatter, parse_frontmatter,  # noqa: E402
                    write_text_verified, console_encoding)

console_encoding()

L1_DIRS = ("wiki/concepts", "wiki/topics")
URL_RE = re.compile(r"^https?://", re.I)
# `## 参见` 是 CLAUDE.md 认可的交叉引用章节；`## 与相邻概念的关系` 优先（更具体）
SEE_SECTIONS = ("## 与相邻概念的关系", "## 参见")
NEW_SEE_HEADING = "## 参见"


# ---------------------------------------------------------------- 解析小工具
def strip_code(md):
    """剔除围栏代码块 —— 代码块内的 `[[…]]` 是示例文本，不是链接（第 4 号事故同型）。"""
    out, fence = [], False
    for ln in md.split("\n"):
        if ln.lstrip().startswith("```"):
            fence = not fence
            out.append("")
            continue
        out.append("" if fence else ln)
    return "\n".join(out)


def norm_entry(link):
    """sources: 条目 → (原样, 去显示文本的目标, basename, 是否 wikilink)。

    与 `qc_evidence_base._resolve_source_name` **同语义**（basename 归一），
    否则「本工具判它 OK、qc_evidence_base 判它 unresolved」会长期打架。
    """
    s = str(link)
    t = s.replace("\\|", "|").split("|")[0].strip().strip('"').strip("'").strip()
    is_wiki = t.startswith("[[")
    if is_wiki:
        t = t[2:]
    if t.endswith("]]"):
        t = t[:-2]
    target = t.strip()
    base = target.replace("\\", "").split("/")[-1].split("#")[0]
    if base.endswith(".md"):
        base = base[:-3]
    return s, target, base, is_wiki


def body_has_link(body, base):
    """正文（已剔代码块）是否已有指向 base 的 wikilink（含别名/锚点写法）。"""
    pat = re.compile(r"\[\[(?:[^\[\]|]*/)?" + re.escape(base)
                     + r"(?:\.md)?(?:[|#][^\[\]]*)?\]\]")
    return bool(pat.search(strip_code(body)))


def body_has_url(body, url):
    return url.rstrip("/") in strip_code(body)


# ---------------------------------------------------------------- 页面清单
def collect_pages():
    """basename -> 相对路径。覆盖 wiki 全部页 + projects 下的 md（含 evidence 页）。

    ⚠️ projects/ 下有 PPT 构建临时目录权限受限（`git status` 都会 warning），
       os.walk 用 onerror 忽略，不能让它中断整轮扫描。
    """
    out = {}
    for f in glob.glob("wiki/*/*.md"):
        out.setdefault(os.path.basename(f)[:-3], f.replace("\\", "/"))
    for dirpath, dirnames, filenames in os.walk("projects", onerror=lambda e: None):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for fn in filenames:
            if fn.endswith(".md"):
                out.setdefault(fn[:-3], os.path.join(dirpath, fn).replace("\\", "/"))
    return out


def collect_source_names():
    """与 qc_evidence_base.build_src_pages 相同的口径（wiki/sources + 项目 source 卡）。"""
    names = set()
    for f in glob.glob("wiki/sources/*.md") + glob.glob("projects/*/sources/*.md"):
        nm = os.path.basename(f)[:-3]
        if nm != "index":
            names.add(nm)
    return names


# ---------------------------------------------------------------- frontmatter 行定位
def find_fm_bounds(lines):
    """返回 (start, end)：frontmatter 内容行的 [start, end) 区间；无 frontmatter 返回 None。"""
    if not lines or lines[0].strip() != "---":
        return None
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            return (1, i)
    return None


def find_sources_block(lines, bounds):
    """定位 `sources:` 键与其条目行。-> dict(key_idx, item_idxs, inline)"""
    s, e = bounds
    key_idx = None
    for i in range(s, e):
        if re.match(r"^sources\s*:", lines[i]):
            key_idx = i
            break
    if key_idx is None:
        return None
    # `sources: []` 是**空块**（本工具自己写出来的形态），不是内联列表——
    # 若不单独识别，每次复跑都会把它报成「内联写法，本工具不改」的假 BLOCKER。
    inline = not (re.match(r"^sources\s*:\s*$", lines[key_idx])
                  or re.match(r"^sources\s*:\s*\[\s*\]\s*$", lines[key_idx]))
    if re.match(r"^sources\s*:\s*\[\s*\]\s*$", lines[key_idx]):
        return {"key_idx": key_idx, "item_idxs": [], "inline": False, "empty": True}
    items = []
    if not inline:
        j = key_idx + 1
        # 🔴 必须与 `kb_lib.parse_frontmatter` 的 `^\s+-\s+` **完全一致**（含「至少一个空格」）。
        #    真 YAML 允许序列项与键同缩进（`sources:` 下 `- item` 顶格），
        #    但本库的轻量解析器**看不见**这种写法 ⇒ 本工具若放宽，就会出现
        #    「工具看到 N 条、库看到 0 条」（CLAUDE.md：校验必须复用被校验系统的解析器）。
        #    这种页会被下面的「条目数≠行数」守卫拦下并报告，属**数据卫生问题**，须人工开 `sources:` 缩进。
        while j < e and re.match(r"^\s+-\s", lines[j]):
            items.append(j)
            j += 1
    return {"key_idx": key_idx, "item_idxs": items, "inline": inline}


def section_span(lines, start_from, headings):
    """在 start_from 之后找第一个匹配的 `## ` 章节，返回 (head_idx, end_idx)。

    end_idx 为该章节最后一行非空行的下一行（插入点）。
    """
    for i in range(start_from, len(lines)):
        if lines[i].strip() in headings:
            end = len(lines)
            for j in range(i + 1, len(lines)):
                if lines[j].startswith("## "):
                    end = j
                    break
            last = i
            for j in range(i + 1, end):
                if lines[j].strip():
                    last = j
            return (i, last + 1)
    return None


# ---------------------------------------------------------------- 规划
def plan_page(rel, text, all_pages, source_names):
    """纯函数：返回规划结果 dict。不读盘、不写盘，便于 selftest 反算。"""
    res = {"page": rel, "drop": [], "append": [], "append_url": [], "external": [],
           "orphan": [], "warn": [], "kept": 0, "inline": False, "no_needs": []}
    a, b = split_frontmatter(text)
    if not a:
        res["orphan"].append({"reason": "frontmatter 不可解析，已跳过"})
        return res
    lines = text.replace("\r\n", "\n").split("\n")
    bounds = find_fm_bounds(lines)
    blk = find_sources_block(lines, bounds) if bounds else None
    if blk is None:
        return res
    res["inline"] = blk["inline"]
    if blk["inline"]:
        res["orphan"].append({"reason": "sources: 为内联写法，本工具不改（需手工）"})
        return res
    fm = parse_frontmatter(a)
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    # 数据卫生：`sources:` 下若是**零缩进**序列项，真 YAML 认、本库解析器不认
    # ⇒ 该字段会被读成空 list（页面「看起来有 sources，实际一条都没挂上」）。
    # 本工具不擅自改缩进（那会改变解析结果），只把它报出来交人工。
    if not blk["inline"] and blk["item_idxs"] == []:
        j = blk["key_idx"] + 1
        while j < bounds[1] and (not lines[j].strip() or lines[j].lstrip().startswith("#")):
            j += 1
        if j < bounds[1] and re.match(r"^-\s", lines[j]):
            res["warn"].append(
                "sources: 下是零缩进序列项（第 %d 行），kb_lib.parse_frontmatter 解析不到"
                "⇒ 该页的 sources 实际为空。须人工把序列项缩进两格。" % (j + 1))
    # 条目行数必须与解析出的条目数一致，否则拒绝规划（防「解析器和工具不同步」）
    if len(srcs) != len(blk["item_idxs"]):
        res["orphan"].append({"reason": "sources 条目数 %d ≠ 行数 %d，拒绝规划"
                              % (len(srcs), len(blk["item_idxs"]))})
        return res
    for n, (link, li) in enumerate(zip(srcs, blk["item_idxs"])):
        raw, target, base, is_wiki = norm_entry(link)
        if is_wiki and base in source_names:
            res["kept"] += 1
            continue
        if is_wiki:
            if base in all_pages:
                res["drop"].append({"line": li, "entry": raw, "base": base,
                                    "target": target,
                                    "to": all_pages[base]})
            else:
                res["orphan"].append({"line": li, "entry": raw, "base": base})
        elif URL_RE.match(target):
            res["external"].append({"line": li, "entry": raw, "url": target})
        else:
            res["orphan"].append({"line": li, "entry": raw, "reason": "非 wikilink 非 URL"})
    # 正文是否已有链接 → 决定「删」还是「删+补」
    for it in res["drop"]:
        if not body_has_link(b, it["base"]):
            res["append"].append({"base": it["base"], "target": it["target"]})
    for it in res["external"]:
        if not body_has_url(b, it["url"]):
            res["append_url"].append({"target": it["url"]})
    return res


# ---------------------------------------------------------------- 改写
TODAY = None


def apply_plan(text, plan, today):
    """纯函数：把规划落到文本（逐行操作，其余字节不变）。返回新文本。

    ⚠️ 空 `sources:` 必须写成 `sources: []`：写成裸 `sources:` 时 YAML 解出 None，
       而 `kb_lint_deep.check_raw_resource_links` 的 `for s in srcs` 会 TypeError
       （它只兜了 str，没兜 None）。实测本库当前 0 处空 sources，别造新的。
    """
    lines = text.replace("\r\n", "\n").split("\n")
    bounds = find_fm_bounds(lines)
    blk = find_sources_block(lines, bounds)
    drop_lines = sorted([d["line"] for d in plan["drop"]] +
                        [d["line"] for d in plan["external"]], reverse=True)
    for li in drop_lines:
        del lines[li]
    # sources: 变空 → 显式写 []
    bounds = find_fm_bounds(lines)
    blk = find_sources_block(lines, bounds)
    if blk is not None and blk["item_idxs"] == []:
        lines[blk["key_idx"]] = "sources: []"
    # updated: 今天
    bounds = find_fm_bounds(lines)
    if bounds:
        s, e = bounds
        for i in range(s, e):
            if re.match(r"^updated\s*:", lines[i]):
                if lines[i].strip() != "updated: %s" % today:
                    lines[i] = "updated: %s" % today
                break
    # 正文补链
    new_bullets = []
    for it in plan["append"]:
        new_bullets.append("- [[%s]]" % it["target"])
    for it in plan.get("append_url", []):
        new_bullets.append(
            "- %s —— **外部链接，无库内 source 卡**（故不在 `sources:` 内）"
            % it["target"])
    if new_bullets:
        bounds = find_fm_bounds(lines)
        start = bounds[1] + 1 if bounds else 0
        span = None
        for h in SEE_SECTIONS:
            span = section_span(lines, start, (h,))
            if span:
                break
        if span is None:
            # 没有可用的交叉引用章节 → 补标准的 `## 参见`（CLAUDE.md 认可，不是自造章节）
            if lines and lines[-1].strip() != "":
                lines.append("")
            lines.append(NEW_SEE_HEADING)
            lines.append("")
            lines.extend(new_bullets)
        else:
            _h, at = span
            lines[at:at] = new_bullets
        # 若插入点紧跟标题，补一个空行，保持库内 `## 参见` 的既有排版
        _ensure_blank_after_heading(lines, new_bullets[0])
    out = "\n".join(lines)
    # 不变量：**末尾换行「有没有」必须与原文件一致**。
    # 2026-10-25 实测踩坑：原文以 `\n` 结尾、且补链落在文件末尾时，
    # `lines` 末元素是空串，join 后末尾换行丢失 ⇒ git 显示
    # `\ No newline at end of file`，把一整行长条目显示成「删除+新增」（噪声）。
    if text.replace("\r\n", "\n").endswith("\n") and not out.endswith("\n"):
        out += "\n"
    return out


def _ensure_blank_after_heading(lines, first_bullet):
    """`## 参见` 标题下先空一行再列条目（库内既有排版）。

    只在插入点**紧跟标题**时补空行；已有序列表的页面不动，避免制造无意义 diff。
    """
    for i, ln in enumerate(lines):
        if ln.strip() == NEW_SEE_HEADING:
            # 找到这次插入的条目（按内容定位，仅当紧跟标题时）
            j = i + 1
            if j < len(lines) and lines[j].strip() != "" and j < len(lines) and lines[j] == first_bullet:
                lines.insert(j, "")
            return


# ---------------------------------------------------------------- 主流程
def run(dry_run=True, report_json=None):
    all_pages = collect_pages()
    source_names = collect_source_names()
    today = datetime.date.today().isoformat()
    targets = []
    for d in L1_DIRS:
        targets.extend(sorted(glob.glob(os.path.join(d, "*.md"))))
    plans, blockers = [], []
    warns = []
    for p in targets:
        rel = p.replace("\\", "/")
        text = read_text(p)
        pl = plan_page(rel, text, all_pages, source_names)
        if pl["orphan"] or pl["drop"] or pl["external"] or pl["warn"]:
            plans.append((p, rel, text, pl))
        if pl["orphan"]:
            blockers.append(pl)
        if pl["warn"]:
            warns.append((rel, pl["warn"]))
    n_drop = sum(len(pl["drop"]) + len(pl["external"]) for _p, _r, _t, pl in plans)
    n_app = sum(len(pl["append"]) + len(pl["append_url"]) for _p, _r, _t, pl in plans)
    print("扫描 %d 个 L1 页（%s）" % (len(targets), " + ".join(L1_DIRS)))
    print("待改页 %d / 删条目 %d（其中外链 %d）/ 正文补链 %d / BLOCKER %d"
          % (len(plans), n_drop,
             sum(len(pl["external"]) for _p, _r, _t, pl in plans), n_app, len(blockers)))
    print()
    for _p, rel, _t, pl in plans:
        print("--- %s  keep=%d 删=%d 补=%d" % (rel, pl["kept"],
                                             len(pl["drop"]) + len(pl["external"]),
                                             len(pl["append"]) + len(pl["append_url"])))
        for d in pl["drop"]:
            mark = "补链" if any(a["base"] == d["base"] for a in pl["append"]) else "删(正文已有)"
            print("    [%s] %s  (%s)" % (mark, d["entry"], d["to"]))
        for d in pl["external"]:
            print("    [外链] %s" % d["entry"])
        for d in pl["orphan"]:
            print("    [BLOCKER] %s" % d)
        for d in pl["warn"]:
            print("    [WARN] %s" % d)
    if blockers:
        print("\n❌ 有 %d 页存在无法判定的条目，**拒绝落盘**（先把真坏链暴露出来）"
              % len(blockers))
    if report_json:
        with open(report_json, "w", encoding="utf-8") as fh:
            json.dump({"today": today,
                       "pages": [{"page": rel, **{k: v for k, v in pl.items() if k != "page"}}
                                 for _p, rel, _t, pl in plans]},
                      fh, ensure_ascii=False, indent=1)
        print("已写 %s" % report_json)
    if dry_run:
        print("\n[干跑] 未写盘。确认后加 --apply。")
        return 0
    if blockers:
        return 2
    # ---- 落盘：先备份，再逐页写，最后复算
    bak = ".qc_backup_%s" % datetime.date.today().strftime("%Y%m%d")
    written = 0
    failed = []
    for p, rel, text, pl in plans:
        new = apply_plan(text, pl, today)
        if new == text.replace("\r\n", "\n"):
            print("[=] %s 无变化（可能 already fixed）" % rel)
            continue
        dst = os.path.join(bak, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(p, dst)
        ok, detail = write_text_verified(p, new, quiet=False, require_frontmatter=True)
        if not ok:
            failed.append((rel, detail))
            continue
        written += 1
        # 写后复算：必须能读回、frontmatter 仍解析、且已无该条目
        back = read_text(p)
        a2, b2 = split_frontmatter(back)
        fm2 = parse_frontmatter(a2)
        srcs2 = fm2.get("sources") or []
        if isinstance(srcs2, str):
            srcs2 = [srcs2]
        left = [norm_entry(s)[2] for s in srcs2
                if norm_entry(s)[3] and norm_entry(s)[2] not in source_names]
        if left:
            failed.append((rel, "写后仍残留未解析条目 %s" % left))
    print("\n落盘：%d 页写入，%d 页失败；备份在 %s/" % (written, len(failed), bak))
    for rel, why in failed:
        print("  [!] %s: %s" % (rel, why))
    return 0 if not failed else 1


# ---------------------------------------------------------------- selftest
def run_selftest():
    ok = True
    n_chk = [0]

    def chk(name, cond, extra=""):
        nonlocal ok
        n_chk[0] += 1
        print(("  PASS  " if cond else "  FAIL  ") + name + (("  " + extra) if extra else ""))
        if not cond:
            ok = False

    print("== qc_sources_drift --selftest ==")
    SRC = {"真源A", "真源B"}
    PAGES = {"概念甲": "wiki/concepts/概念甲.md",
             "主题乙": "wiki/topics/主题乙.md",
             "项目戊": "projects/P/evidence/项目戊.md"}
    fm = ("---\ntype: concept\ntags: [x]\nsummary: \"s\"\n"
          "sources:\n  - \"[[sources/真源A.md]]\"\n  - \"[[concepts/概念甲]]\"\n"
          "  - \"[[concepts/不存在的页]]\"\n"
          "  - \"https://github.com/karpathy/llm-wiki\"\nupdated: 2026-01-01\n---\n"
          "# 标题\n\n正文提到别的东西。\n\n## 参见\n\n- [[sources/真源A]]\n")

    pl = plan_page("wiki/concepts/T.md", fm, PAGES, SRC)
    chk("真 source 卡被保留", pl["kept"] == 1, "kept=%d" % pl["kept"])
    chk("L1 条目被移出（1 条）", len(pl["drop"]) == 1 and pl["drop"][0]["base"] == "概念甲")
    chk("外部 URL 被识别", len(pl["external"]) == 1 and "github.com" in pl["external"][0]["url"])
    chk("不存在的目标 → BLOCKER 而非静默删除",
        len(pl["orphan"]) == 1 and pl["orphan"][0]["base"] == "不存在的页")
    chk("正文无链接 → 需补链（1 条）", len(pl["append"]) == 1 and pl["append"][0]["base"] == "概念甲")
    chk("正文无该外链 → 需补「无 source 卡」注记", len(pl["append_url"]) == 1)

    new = apply_plan(fm, pl, "2026-10-25")
    a2, b2 = split_frontmatter(new)
    fm2 = parse_frontmatter(a2)
    chk("改写后 frontmatter 仍可解析", bool(a2))
    srcs2 = fm2.get("sources") or []
    chk("真源保留 + BLOCKER 条目不被删除（留给人工）",
        srcs2 == ["[[sources/真源A.md]]", "[[concepts/不存在的页]]"], str(srcs2))
    chk("updated 改为今天", fm2.get("updated") == "2026-10-25", str(fm2.get("updated")))
    chk("正文补到 ## 参见 下", "- [[concepts/概念甲]]" in b2, "")
    chk("外链注明无 source 卡", "无库内 source 卡" in new)

    # 反例：正文已有链接 → 只删不补（避免重复条目）
    fm_b = fm.replace("正文提到别的东西。", "正文提到 [[concepts/概念甲|甲]]。")
    pl_b = plan_page("x", fm_b, PAGES, SRC)
    chk("正文已有链接 → 不重复补",
        len(pl_b["drop"]) == 1 and len(pl_b["append"]) == 0 and len(pl_b["append_url"]) == 1,
        "append=%d append_url=%d" % (len(pl_b["append"]), len(pl_b["append_url"])))

    # 反例：代码块里的 [[...]] 不算链接
    fm_c = fm.replace("正文提到别的东西。", "```\n[[concepts/概念甲]]\n```\n")
    pl_c = plan_page("x", fm_c, PAGES, SRC)
    chk("代码块内 wikilink 不算正文已有", len(pl_c["append"]) == 1)

    # 反例：无 frontmatter / 内联 sources 一律拒绝
    pl_d = plan_page("x", "# 只有正文\n", PAGES, SRC)
    chk("无 frontmatter → 拒绝（BLOCKER）", len(pl_d["orphan"]) == 1)
    pl_e = plan_page("x", "---\nsources: [\"[[concepts/概念甲]]\"]\n---\n", PAGES, SRC)
    chk("内联 sources → 不动，报给人工", pl_e["inline"] and len(pl_e["orphan"]) == 1)

    # 反例：`sources:` 块内夹注释行 → 行数对不上，拒绝规划（防「解析器与工具不同步」）
    bad = ("---\nsources:\n  # 说明注释\n  - \"[[sources/真源A.md]]\"\nupdated: 2026-01-01\n---\n")
    pl_f = plan_page("x", bad, PAGES, SRC)
    chk("条目数≠行数 → 拒绝规划",
        any("拒绝规划" in o.get("reason", "") for o in pl_f["orphan"]), str(pl_f["orphan"]))

    # 反例：**零缩进**序列项 —— 真 YAML 合法，但 `kb_lib.parse_frontmatter` 的
    # `^\s+-\s+` 看不见它 ⇒ 本工具必须同样看不见，并由「条目数≠行数」守卫拦下。
    # （若放宽成 `^\s*-\s`，就会出现「工具看到 2 条、库看到 0 条」——
    #   CLAUDE.md：校验必须复用被校验系统的解析器。）
    flat = ("---\nsources:\n- \"[[sources/真源A.md]]\"\n- \"[[concepts/概念甲]]\"\n"
            "updated: 2026-01-01\n---\n# T\n\n正文。\n")
    pl_j = plan_page("x", flat, PAGES, SRC)
    chk("零缩进序列项（库解析器看不见）→ 报 WARN 且不擅自动手",
        pl_j["kept"] == 0 and len(pl_j["drop"]) == 0 and len(pl_j["warn"]) == 1,
        str(pl_j["warn"]))

    # 幂等：对已修好的文本再规划，应为 0 改动
    pl2 = plan_page("x", new, PAGES, SRC)
    chk("幂等：再跑一遍 0 改动",
        len(pl2["drop"]) == 0 and len(pl2["external"]) == 0 and len(pl2["append"]) == 0)

    # 空 sources 必须写 `sources: []`（裸 sources: 解出 None 会让 lint 的
    # `for s in srcs` 抛 TypeError——本库现有 0 处空 sources，不能造新的）
    only_url = ("---\ntype: concept\nsources:\n  - \"https://example.com/x\"\n"
                "updated: 2026-01-01\n---\n# T\n\n正文。\n")
    pl_g = plan_page("x", only_url, PAGES, SRC)
    new_g = apply_plan(only_url, pl_g, "2026-10-25")
    a3, _ = split_frontmatter(new_g)
    fm3 = parse_frontmatter(a3)
    chk("空 sources 写成 []", "sources: []" in new_g)
    chk("空 sources 解析为 list 而不是 None", fm3.get("sources") == [], repr(fm3.get("sources")))
    chk("kb_lint A1 的 `for s in srcs` 不会 TypeError（None 已排除）",
        not isinstance(fm3.get("sources"), type(None)))
    # 回归：`sources: []` 是**空块**而不是「内联写法」（否则每次复跑都报假 BLOCKER）
    pl_g2 = plan_page("x", new_g, PAGES, SRC)
    chk("`sources: []` 复跑 → 无动作、无 BLOCKER",
        pl_g2["orphan"] == [] and pl_g2["drop"] == [] and pl_g2["inline"] is False,
        str(pl_g2["orphan"]))

    # 章节落点：已有 `## 与相邻概念的关系` 时优先放那里
    two = ("---\ntype: concept\nsources:\n  - \"[[concepts/概念甲]]\"\n"
           "updated: 2026-01-01\n---\n# T\n\n## 与相邻概念的关系\n\n- 已有条目\n\n## 参见\n\n- x\n")
    pl_h = plan_page("x", two, PAGES, SRC)
    new_h = apply_plan(two, pl_h, "2026-10-25")
    seg = new_h.split("## 与相邻概念的关系")[1].split("## 参见")[0]
    chk("优先插入 ## 与相邻概念的关系", "- [[concepts/概念甲]]" in seg)

    # 无可用章节 → 补标准 `## 参见`（CLAUDE.md 认可的交叉引用章节）
    none_sec = ("---\ntype: concept\nsources:\n  - \"[[concepts/概念甲]]\"\n"
                "updated: 2026-01-01\n---\n# T\n\n正文。\n")
    pl_i = plan_page("x", none_sec, PAGES, SRC)
    new_i = apply_plan(none_sec, pl_i, "2026-10-25")
    chk("无章节时补 ## 参见", "## 参见" in new_i and "- [[concepts/概念甲]]" in new_i)
    chk("末尾换行不丢失（原文有 \\n 则保留）", new_i.endswith("\n"))
    no_nl = none_sec.rstrip("\n")
    new_k = apply_plan(no_nl, plan_page("x", no_nl, PAGES, SRC), "2026-10-25")
    chk("末尾无换行的文件也不擅自补（保持原状）", not new_k.endswith("\n"))

    print("\n%s (%d 项断言)" % ("全部 PASS" if ok else "有 FAIL", n_chk[0]))
    return 0 if ok else 1


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(__doc__)
        return 0
    if "--selftest" in args:
        return run_selftest()
    dry = "--apply" not in args
    rj = None
    if "--json" in args:
        i = args.index("--json")
        rj = args[i + 1] if i + 1 < len(args) else None
    return run(dry_run=dry, report_json=rj)


if __name__ == "__main__":
    sys.exit(main())
